import java.util.Stack;

class TypeFrame {
    private Stack<String> outputFrameStack = new Stack<>();

    private void pop(final String descriptor) {
        if (descriptor.charAt(0) == '(') {
            int index = 1;
            while (descriptor.charAt(index) != ')') {
                index = popType(descriptor, index);
            }
        } else {
            popType(descriptor, 0);
        }
    }

    private int popType(final String descriptor, int index) {
        switch (descriptor.charAt(index)) {
            case 'B':
            case 'C':
            case 'D':
            case 'F':
            case 'I':
            case 'S':
            case 'Z':
            case 'L':
                while (descriptor.charAt(index) != ';') {
                    index++;
                }
                break;
            case '[':
                while (descriptor.charAt(index) == '[') {
                    index++;
                }
                index = popType(descriptor, index);
                break;
        }
        outputFrameStack.pop();
        return index + 1;
    }

    public static void main(String[] args) {
        TypeFrame typeFrame = new TypeFrame();
        // Example usage
        typeFrame.outputFrameStack.push("int");
        typeFrame.outputFrameStack.push("double");
        typeFrame.outputFrameStack.push("java/lang/String");
        typeFrame.pop("(IDLjava/lang/String;)V");
    }
}

