import org.jgrapht.GraphFactory;
import org.jgrapht.graph.DefaultEdge;
import org.jgrapht.graph.SimpleGraph;

public class BipartiteGraphGenerator<V, E extends DefaultEdge> {

    @Override
    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        if (target == null || resultMap == null) {
            throw new IllegalArgumentException("Target graph and result map cannot be null");
        }

        // Assuming resultMap contains two keys: "set1" and "set2" for the two partitions
        if (!resultMap.containsKey("set1") || !resultMap.containsKey("set2")) {
            throw new IllegalArgumentException("Result map must contain keys 'set1' and 'set2'");
        }

        V set1 = resultMap.get("set1");
        V set2 = resultMap.get("set2");

        // Assuming set1 and set2 are collections of vertices
        if (!(set1 instanceof Iterable) || !(set2 instanceof Iterable)) {
            throw new IllegalArgumentException("Values for 'set1' and 'set2' must be iterable collections of vertices");
        }

        Iterable<V> partition1 = (Iterable<V>) set1;
        Iterable<V> partition2 = (Iterable<V>) set2;

        for (V vertex1 : partition1) {
            for (V vertex2 : partition2) {
                target.addEdge(vertex1, vertex2);
            }
        }
    }

    public static void main(String[] args) {
        Graph<String, DefaultEdge> graph = new SimpleGraph<>(DefaultEdge.class);
        BipartiteGraphGenerator<String, DefaultEdge> generator = new BipartiteGraphGenerator<>();

        Map<String, Iterable<String>> resultMap = Map.of(
            "set1", List.of("A", "B"),
            "set2", List.of("C", "D")
        );

        generator.generateGraph(graph, resultMap);

        // Print the edges to verify
        graph.edgeSet().forEach(edge -> 
            System.out.println(edge.getSource() + " - " + edge.getTarget())
        );
    }
}

