public class GraphTraversal<V> implements Iterator<V> {
    private Set<V> visited;
    private Set<V> allVertices;

    public GraphTraversal(Set<V> allVertices) {
        this.allVertices = allVertices;
        this.visited = new java.util.HashSet<>();
    }

    @Override
    public boolean hasNext() {
        return !visited.containsAll(allVertices);
    }

    @Override
    public V next() {
        for (V vertex : allVertices) {
            if (!visited.contains(vertex)) {
                visited.add(vertex);
                return vertex;
            }
        }
        throw new java.util.NoSuchElementException();
    }

    @Override
    public void remove() {
        throw new UnsupportedOperationException();
    }
}

