        Box2D rightBox = new Box2D(new Vector2D(midX, y1), new Vector2D(x2, y2));

        return Pair.of(leftBox, rightBox);
    }

    public static void main(String[] args) {
        Box2D box = new Box2D(new Vector2D(0, 0), new Vector2D(10, 10));
        Pair<Box2D, Box2D> result = splitAlongXAxis(box);
        System.out.println("Left Box: " + result.getLeft());
        System.out.println("Right Box: " + result.getRight());
