import org.jgrapht.Graph;
import org.jgrapht.GraphPath;
import org.jgrapht.Graphs;
import org.jgrapht.graph.GraphPathImpl;
import java.util.*;

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0.0);
    }

    Map<V, List<E>> adjacencyList = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        adjacencyList.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
        if (!graph.getType().isDirected()) {
            adjacencyList.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
        }
    }

    V startVertex = adjacencyList.keySet().iterator().next();
    List<E> pathEdges = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();
    Deque<V> stack = new ArrayDeque<>();
    stack.push(startVertex);

    while (!stack.isEmpty()) {
        V current = stack.peek();
        List<E> edges = adjacencyList.get(current);
        boolean foundUnvisitedEdge = false;
        for (E edge : edges) {
            if (!visitedEdges.contains(edge)) {
                visitedEdges.add(edge);
                pathEdges.add(edge);
                V next = Graphs.getOppositeVertex(graph, edge, current);
                stack.push(next);
                foundUnvisitedEdge = true;
                break;
            }
        }
        if (!foundUnvisitedEdge) {
            stack.pop();
        }
    }

    return new GraphPathImpl<>(graph, startVertex, Graphs.getPathVertexList(graph, pathEdges), Graphs.getPathWeight(graph, pathEdges));
}

