import com.dyuproject.protostuff.Schema;
import java.io.IOException;
import java.io.OutputStream;

public class ProtostuffUtil {

    /**
     * Serializes the {@code message}, prefixed with its length, into an {@link OutputStream}.
     * @return the size of the message
     */
    public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
        final byte[] protostuff;
        try {
            protostuff = ProtostuffIOUtil.toByteArray(message, schema, buffer);
        } finally {
            buffer.clear();
        }
        int size = protostuff.length;
        ProtostuffIOUtil.writeRawVarInt32(out, size);
        out.write(protostuff);
        return size;
    }
}

